// static
bool StructTraits<::webnn::mojom::TensorUsage::DataView, ::webnn::mojom::TensorUsagePtr>::Read(
    ::webnn::mojom::TensorUsage::DataView input,
    ::webnn::mojom::TensorUsagePtr* output) {
  bool success = true;
  ::webnn::mojom::TensorUsagePtr result(::webnn::mojom::TensorUsage::New());
  
      if (success)
        result->web_gpu_interop = input.web_gpu_interop();
      if (success)
        result->read = input.read();
      if (success)
        result->write = input.write();
  *output = std::move(result);
  return success;
}


// static
bool StructTraits<::webnn::mojom::TensorInfo::DataView, ::webnn::mojom::TensorInfoPtr>::Read(
    ::webnn::mojom::TensorInfo::DataView input,
    ::webnn::mojom::TensorInfoPtr* output) {
  bool success = true;
  ::webnn::mojom::TensorInfoPtr result(::webnn::mojom::TensorInfo::New());
  
      if (success && !input.ReadDescriptor(&result->descriptor))
        success = false;
      if (success && !input.ReadUsage(&result->usage))
        success = false;
  *output = std::move(result);
  return success;
}

// static
bool UnionTraits<::webnn::mojom::ReadTensorResult::DataView, ::webnn::mojom::ReadTensorResultPtr>::Read(
    ::webnn::mojom::ReadTensorResult::DataView input,
    ::webnn::mojom::ReadTensorResultPtr* output) {
  using UnionType = ::webnn::mojom::ReadTensorResult;
  using Tag = UnionType::Tag;

  switch (input.tag()) {
    case Tag::kBuffer: {
      ::mojo_base::BigBuffer result_buffer{};
      if (!input.ReadBuffer(&result_buffer))
        return false;

      *output = UnionType::NewBuffer(
          std::move(result_buffer));
      break;
    }
    case Tag::kError: {
      ::webnn::mojom::ErrorPtr result_error{};
      if (!input.ReadError(&result_error))
        return false;

      *output = UnionType::NewError(
          std::move(result_error));
      break;
    }
    default:

      return false;
  }
  return true;
}

